/*
 * Offline support. GENERATED by tools/build-sw.js from tools/sw.template.js: do not edit sw.js
 * by hand, edit the template and run `node tools/build-sw.js`.
 *
 * - Install: every file of the site (all languages, both themes) is stored in a cache named
 *   after a hash of the files, so a new deploy gives a new cache and old ones are removed.
 * - Online: pages and files are fetched from the network first (so updates show up straight
 *   away) and the cache is refreshed; if the network fails or is slow, the cached copy is used.
 * - Third-party files (fonts, PDF/Excel libraries) are cached on first use, then served from
 *   the cache.
 */
'use strict';
const CACHE = __VERSION__;
const PREFIX = __PREFIX__;
const FILES = __FILES__;
const EXTERNAL = __EXTERNAL__;
const FONT_CSS = __FONT_CSS__;
const NETWORK_TIMEOUT = 4000;
const SCOPE = new URL('./', self.location).href;

// Same-origin cache key: no query string, and ".../index.html" is stored as ".../".
function key(request) {
  const url = new URL(request.url);
  return url.origin + url.pathname.replace(/\/index\.html$/, '/');
}

async function cacheExternal(cache, url) {
  try {
    const res = await fetch(url, { mode: 'cors', cache: 'reload' });
    if (res.ok) await cache.put(url, res.clone());
    return res;
  } catch (e) { return null; }
}

self.addEventListener('install', (event) => {
  self.skipWaiting();
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await cache.addAll(FILES.map((f) => new Request(f, { cache: 'reload' })));
    // Optional extras: the app still works offline without them (fallback fonts, no export).
    await Promise.all(EXTERNAL.map((url) => cacheExternal(cache, url)));
    await Promise.all(FONT_CSS.map(async (url) => {
      const res = await cacheExternal(cache, url);
      if (!res || !res.ok) return;
      const css = await res.text();
      const fonts = [...css.matchAll(/url\((https:[^)'"]+)\)/g)].map((m) => m[1]);
      await Promise.all(fonts.map((f) => cacheExternal(cache, f)));
    }));
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter((n) => n.startsWith(PREFIX) && n !== CACHE).map((n) => caches.delete(n)));
    await self.clients.claim();
  })());
});

async function fromCache(request, isPage) {
  const cache = await caches.open(CACHE);
  return (await cache.match(key(request))) || (isPage ? cache.match(SCOPE) : undefined);
}

async function networkFirst(event) {
  const request = event.request;
  const isPage = request.mode === 'navigate';
  const network = fetch(request).then(async (res) => {
    if (res.ok && res.type === 'basic') {
      const cache = await caches.open(CACHE);
      await cache.put(key(request), res.clone());
    }
    return res;
  });
  event.waitUntil(network.catch(() => {}));
  // Slow network: answer from the cache after a few seconds, keep the download going.
  const slow = new Promise((resolve) => setTimeout(resolve, NETWORK_TIMEOUT))
    .then(() => fromCache(request, isPage));
  try {
    return await Promise.race([network, slow.then((hit) => hit || network)]);
  } catch (err) {
    const hit = await fromCache(request, isPage);
    if (hit) return hit;
    throw err;
  }
}

async function cacheFirst(request) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(request.url);
  if (hit) return hit;
  const res = await fetch(request);
  if (res.ok || res.type === 'opaque') await cache.put(request.url, res.clone());
  return res;
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin === self.location.origin) {
    if (url.href.startsWith(SCOPE)) event.respondWith(networkFirst(event));
  } else if (url.protocol === 'https:' && (EXTERNAL.includes(url.href) || FONT_CSS.length && /^fonts\.(googleapis|gstatic)\.com$/.test(url.hostname))) {
    event.respondWith(cacheFirst(request));
  }
});
